var track = root.querySelector('.sel3-radio-slide-track');
var thumb = root.querySelector('.sel3-radio-slide-thumb');
var opts = [].slice.call(root.querySelectorAll('.sel3-radio-slide-opt'));
var inputs = [].slice.call(root.querySelectorAll('.sel3-radio-slide-input'));
var uid = 'sel3rs-' + Math.random().toString(36).slice(2, 9);
var jumpT = 0;
function activeIndex(){
  for (var i = 0; i < inputs.length; i++){ if (inputs[i].checked) return i; }
  return 0;
}
function place(animate){
  var opt = opts[activeIndex()];
  if (!opt) return;
  thumb.style.height = opt.offsetHeight + 'px';
  thumb.style.transform = 'translateY(' + opt.offsetTop + 'px)';
  if (animate){
    thumb.classList.remove('sel3-radio-slide-jump');
    void thumb.offsetWidth;
    thumb.classList.add('sel3-radio-slide-jump');
    clearTimeout(jumpT);
    jumpT = setTimeout(function(){ thumb.classList.remove('sel3-radio-slide-jump'); }, 470);
  }
}
inputs.forEach(function(inp){
  inp.name = uid;
  inp.addEventListener('change', function(){ place(true); });
});
requestAnimationFrame(function(){ place(false); });
if (window.ResizeObserver){
  var ro = new ResizeObserver(function(){ place(false); });
  ro.observe(track);
}

